  xiu28: `\u4E8C\u5341\u516B\u5BBF\u7EAA\u5F8B: \u62A5\u503C\u5BBF+\u56DB\u8C61+\u4E00\u53E5\u8BDD\u542B\u4E49;\u7B49\u5206\u7B80\u5316\u53E3\u5F84\u5DF2\u5728\u76D8\u9762\u58F0\u660E;\u4E0D\u5C55\u5F00\u5409\u51F6\u65AD\u8BED\u3002`,
  transits: `\u884C\u8FD0\u89E3\u8BFB\u951A\u70B9: \u53EA\u770B\u6162\u661F(\u67281\u5BAB/\u5E74\u3001\u571F2.5\u5E74/\u5BAB\u3001\u5929\u6D77\u51A5\u4E16\u4EE3\u4F46\u8FC7\u8F74/\u5408\u4E2A\u4EBA\u661F\u65F6\u751F\u6548);\u89E6\u53D1\u89C4\u5219(\u7ECF\u9A8C\u53E3\u5F84): \u884C\u8FD0\u8FC7\u56DB\u8F74\xB12\xB0=\u4EBA\u751F\u7AE0\u8282\u7FFB\u9875;\u571F\u661F\u5408ASC=\u6210\u4EBA\u793C/\u51B2ASC=\u5173\u7CFB\u8003\u9898/\u5408MC=\u4E8B\u4E1A\u5B9A\u8C03;\u6728\u661F\u56DE\u5F52\u672C\u547D\u6728\u661F\u224812\u5E74=\u6269\u5F20\u5E74;\u51A5\u738B\u5211\u51B2MC/ASC=\u6DF1\u5EA6\u91CD\u6784(\u8FC7\u7A0B1-3\u5E74);\u5929\u661F\u5408\u672C\u547D\u65E5\u6708\u91D1=\u9AA4\u53D8\u3002\u65E5\u671F\u5FC5\u987B\u5F15\u7528\u76D8\u9762\u7B97\u51FA\u7684\u65F6\u95F4\u7A97,\u7981"2027\u5E74\u5DE6\u53F3"\u5F0F\u5E9F\u8BDD\u3002\u5185\u884C\u661F\u53EA\u7528\u4E8E\u6D41\u6708\u7CBE\u4FEE\u4E0D\u8FDB\u5E74\u5EA6\u7ED3\u8BBA\u3002`,
  progressions: `\u6B21\u9650\u951A\u70B9: 1\u5929=1\u5E74;\u53EA\u770B\u6B21\u9650\u592A\u9633(\u7EA630\u5E74\u6362\u4E00\u5BAB)/\u6708\u4EAE(2.5\u5E74\u6362\u5BAB,\u60C5\u7EEA\u4E3B\u9898)/\u6C34\u91D1(\u5185\u5316\u6001\u5EA6);\u6B21\u9650\u65E5\u6708\u5408/\u51B2(\u7EA629.5\u5E74)=\u4EBA\u751F\u5927\u8282\u70B9\u3002`,
  profection: `\u5C0F\u9650\u951A\u70B9: \u5E74\u5BAB=(\u5E74\u9F84mod12)+1\u81EA\u4E0A\u5347\u8D77;1/7/4/10\u5BAB\u6FC0\u6D3B\u5E74=\u81EA\u8EAB/\u5173\u7CFB/\u5BB6\u4E1A/\u4E8B\u4E1A\u4E3B\u9898;\u5E74\u4E3B\u661F=\u5F53\u5E74\u5173\u952E\u8BCD,\u5176\u672C\u547D\u72B6\u6001\u5B9A\u987A\u9006;\u4E0E\u884C\u8FD0\u53CC\u91CD\u9A8C\u8BC1\u624D\u7ED9\u5F3A\u7ED3\u8BBA\u3002`,
  firdaria: `\u6CD5\u8FBE\u951A\u70B9: \u5F53\u524D\u4E3B\u9650\u661F+\u7ED3\u675F\u5E74\u9F84;\u89E3\u91CA\u8BE5\u661F\u672C\u547D\u72B6\u6001(\u843D\u5EA7\u843D\u5BAB\u76F8\u4F4D);\u7ECF\u9A8C\u7CFB\u7EDF,\u58F0\u660E\u4E4B\u3002`,
  solar_return: `\u592A\u9633\u8FD4\u7167\u951A\u70B9: \u53EA\u770B\u8FD4\u7167ASC\u3001MC\u3001\u65E5\u6708\u5408\u76F8\u6240\u5728\u5BAB\u3001\u56DB\u8F74\u9644\u8FD1\u661F\u3001\u547D\u4E3B\u661F\u53BB\u5411;\u6709\u6548\u671F\u5230\u4E0B\u4E2A\u751F\u65E5;\u5750\u6807\u7528\u51FA\u751F\u5730(\u73B0\u5C45\u5730\u4E0D\u540C\u4F1A\u53D8,\u5DF2\u5728\u76D8\u9762\u58F0\u660E)\u3002`,
  bazi_liunian: `\u6D41\u5E74\u951A\u70B9: \u6D41\u5E74\u5E72\u652F\u4E0E\u539F\u5C40\u56DB\u652F\u7684\u5211\u51B2\u5408\u5BB3\u7834+\u4E0E\u65E5\u4E3B\u5341\u795E(\u5B98\u6740=\u804C\u4F4D\u7EA6\u675F/\u5370=\u8D44\u8D28\u9760\u5C71/\u98DF\u4F24=\u4F5C\u54C1\u8868\u8FBE/\u8D22=\u6536\u5165/\u6BD4\u52AB=\u540C\u4FAA\u7ADE\u4E89)+\u662F\u5426\u586B\u7A7A\u4EA1/\u51B2\u7A7A\u4EA1/\u5F15\u52A8\u7F8A\u5203\u7984\u795E;\u53E0\u52A0\u5F53\u524D\u5927\u8FD0\u4E00\u8D77\u8BF4;\u7ED9\u65F6\u95F4\u7A97\u4E0D\u7ED9\u91D1\u989D\u3002`,
  ziwei_dayun: `\u7D2B\u5FAE\u884C\u8FD0\u951A\u70B9: \u5F53\u524D\u5927\u9650\u5BAB\u7684\u56DB\u5316+\u4E3B\u661F\u91CD\u4E8E\u672C\u547D;\u6D41\u5E74\u5BAB=\u5F53\u5E74\u5730\u652F\u6240\u5728\u5BAB;\u6D41\u5E74\u56DB\u5316\u6309\u5E74\u5E72\u518D\u53E0\u4E00\u5C42(\u76D8\u9762\u5DF2\u7ED9);\u884C\u8FD0\u4F18\u5148\u7EA7=\u5927\u9650>\u6D41\u5E74>\u672C\u547D\u3002`,
  synastry: `\u5408\u76D8\u951A\u70B9: \u76F8\u4F4D\u77E9\u9635\u91CC\u91CD\u70B9\u8BB2"\u8C01\u7684\u884C\u661F\u538B\u8C01\u7684\u70B9"(\u4F20\u7EDF\u8BF4\u6CD5\u8981\u6807\u6CE8);A\u7684\u571F\u661F\u5408B\u7684\u592A\u9633=\u7EA6\u675F\u65B9;\u91D1\u706B\u76F8\u4F4D=\u5438\u5F15;\u65E5\u6708\u76F8\u4F4D=\u957F\u671F\u76F8\u5904;ASC/MC\u4EA4\u53C9=\u5916\u5728\u4E92\u52A8\u65B9\u5F0F;\u53CC\u65B9\u4E09\u5927\u4EF6(\u65E5\u6708\u5347)\u5148\u5404\u81EA\u4E00\u53E5\u8BDD\u518D\u4EA4\u53C9\u3002`,
  composite: `\u7EC4\u5408\u76D8\u951A\u70B9: \u7EC4\u5408\u76D8=\u5173\u7CFB\u7684"\u81EA\u5DF1";\u770B\u4E2D\u70B9\u661F\u843D\u5EA7+\u843D\u5BAB(\u76D8\u9762\u4EE5A\u76D8\u5BAB\u4F4D\u8FD1\u4F3C);\u65E5\u6708\u4E2D\u70B9=\u5173\u7CFB\u6838\u5FC3\u9A71\u52A8\u529B;\u571F\u661F=\u5173\u7CFB\u7684\u529F\u8BFE;\u58F0\u660E\u4E2D\u70B9\u6CD5\u53E3\u5F84\u3002`,
  bazi_hehun: `\u5408\u5A5A\u951A\u70B9(\u9010\u6761\u7ED9\u4F9D\u636E): \u2460\u5E74\u652F\u5173\u7CFB(\u516D\u5408/\u4E09\u5408=\u987A,\u51B2/\u5211/\u5BB3=\u6469\u64E6,\u58F0\u660E\u6982\u7387\u503E\u5411\u975E\u5224\u51B3);\u2461\u65E5\u67F1: \u65E5\u5E72\u4E94\u5408+\u65E5\u652F\u516D\u5408\u4E09\u5408=\u9AD8\u5206,\u5929\u514B\u5730\u51B2=\u6469\u64E6\u6700\u91CD;\u2462\u7528\u795E\u4E92\u8865=\u5BF9\u65B9\u683C\u5C40\u4E94\u884C\u6070\u4E3A\u6211\u7684\u559C\u7528(\u6700\u5B9E\u7528\u4E00\u6761);\u2463\u6843\u82B1\u4E92\u5750/\u65E5\u652F\u4E92\u4E3A\u5929\u4E59\u8D35\u4EBA\u5355\u72EC\u5217\u51FA;\u2464\u8F93\u51FA\u53CC\u65B9\u56DB\u67F1\u5BF9\u7167+\u9010\u6761\u4F9D\u636E;\u7EA2\u7EBF: \u4E0D\u51FA"\u5FC5\u79BB""\u514B\u6B7B"\u65AD\u8BED\u3002`,
  zodiac_match: `\u901F\u914D\u7EAA\u5F8B: \u7EAF\u5A31\u4E50\u7EA7,\u58F0\u660E\u4E4B;\u592A\u9633\u661F\u5EA7\u9897\u7C92\u5EA6\u6781\u7C97;\u60F3\u8BA4\u771F\u770B\u8BF7\u7528\u5408\u76D8/\u5408\u5A5A\u3002`,
